/**
 * Roster grade percentiles, generated from 11th-edition tournament lists (2,000 points, events from 20 June to
 * 8 November 2026) that import cleanly; only these percentiles are kept. Each array holds a value at every fifth
 * percentile, 0th to 100th, as `rosterGrades` measures it, every value higher for a list that does the job better.
 *
 * Smaller battle sizes are random sub-lists drawn from the tournament lists' own units, and Onslaught joins a
 * list with a 1,000-point draw from another list of its faction.
 */
import type { MetricKey, ReferenceTargetKey } from './rosterGrades'

/** The battle sizes the tournament lists are drawn at; any other limit is compared with the nearest. */
export type CalibratedSize = 600 | 1000 | 2000 | 3000

/** The targets at least nine in ten tournament lists of each size have a unit to take half of alone, so lacking one is worth naming. */
export const EXPECTED_TOOLS: Record<CalibratedSize, readonly ReferenceTargetKey[]> = {
  600: ['vehicle', 'monster'],
  1000: ['horde', 'vehicle', 'monster'],
  2000: ['horde', 'elite', 'vehicle', 'heavyVehicle', 'monster'],
  3000: ['horde', 'elite', 'vehicle', 'heavyVehicle', 'monster'],
}

export type Peers = {
  measures: Partial<Record<MetricKey, readonly number[]>>
  /** Each category's average measure percentile. */
  categories: Record<string, readonly number[]>
  /** The average category percentile. */
  overall: readonly number[]
}

/**
 * Tournament lists of one faction and size, keyed by the faction's catalogue id, or of every faction under ''.
 * Only factions with at least 40 tournament lists have their own.
 */
